    out.push(`2^${n}:${(agree / tot).toFixed(4)}`);
  }
  console.log(`G  agreement rate of c(t) and c(t + 2^n) over ${T2} terms: ${out.join(' ')}`);
  // a control: shifts that are not powers of two
  const ctl = [];
  for (const s of [3, 5, 7, 11, 1000, 12345]) {
